53	const ITEM_BASE_PREMIUMS: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	const FIRST_INSURANCE_RATE = 0.1;
62	const CURSE_SURCHARGE_RATE = 0.5;
63	const HIGH_ENCHANTMENT_THRESHOLD = 5;
64	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
65	const PROCESSING_FEE = 5;
66	const LOYALTY_YEARS_THRESHOLD = 2;
67	const LOYALTY_DISCOUNT_RATE = 0.2;
68	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
69	const ALIKE_BLOCK_SIZE = 3;
70	const ALIKE_BLOCK_PREMIUM = 60;
71	
72	const countItemsByType = (items: QuoteItem[]): Map<string, number> => {
73	  const countsByType = new Map<string, number>();
74	  for (const item of items) {
75	    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
76	  }
77	  return countsByType;
78	};
79	
80	const premiumForAlikeGroup = (type: string, count: number): number => {
81	  if (!(type in ITEM_BASE_PREMIUMS)) {
82	    throw new Error(`Unknown item type: ${type}`);
83	  }
84	  const formsExactlyOneBlock = count === ALIKE_BLOCK_SIZE;
85	  return formsExactlyOneBlock
86	    ? ALIKE_BLOCK_PREMIUM
87	    : count * ITEM_BASE_PREMIUMS[type];
88	};
89	
90	const calculatePolicyBasePremium = (items: QuoteItem[]): number => {
91	  let total = 0;
92	  for (const [type, count] of countItemsByType(items)) {
93	    total += premiumForAlikeGroup(type, count);
94	  }
95	  return total;
96	};
97	
98	const itemSurcharge = (
99	  items: QuoteItem[],
100	  applies: (item: QuoteItem) => boolean,
101	  rate: number,
102	): number =>
103	  items.reduce(
104	    (sum, item) =>
105	      applies(item) ? sum + ITEM_BASE_PREMIUMS[item.type] * rate : sum,
106	    0,
107	  );
108	
109	const calculateCurseSurcharge = (items: QuoteItem[]): number =>
110	  itemSurcharge(items, (item) => item.cursed === true, CURSE_SURCHARGE_RATE);
111	
112	const calculateHighEnchantmentSurcharge = (items: QuoteItem[]): number =>
113	  itemSurcharge(
114	    items,
115	    (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
116	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
117	  );
118	
119	const calculateQuotePremium = (
120	  items: QuoteItem[],
121	  customer: Customer,
122	  isFollowUpContract: boolean,
123	): number => {
124	  const policyBasePremium = calculatePolicyBasePremium(items);
125	  const curseSurcharge = calculateCurseSurcharge(items);
126	  const highEnchantmentSurcharge = calculateHighEnchantmentSurcharge(items);
127	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_RATE;
128	  const loyaltyDiscount =
129	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
130	      ? policyBasePremium * LOYALTY_DISCOUNT_RATE
131	      : 0;
132	  const followUpDiscount = isFollowUpContract
133	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
134	    : 0;
135	  return Math.ceil(
136	    policyBasePremium +
137	      curseSurcharge +
138	      highEnchantmentSurcharge +
139	      firstInsuranceSurcharge -
140	      loyaltyDiscount -
141	      followUpDiscount +
142	      PROCESSING_FEE,
143	  );
144	};
145	
146	const ITEM_INSURANCE_VALUES: Record<string, number> = {
147	  sword: 1000,
148	  amulet: 600,
149	  rune: 250,
150	};
151	const DEDUCTIBLE = 100;
152	const PAYOUT_CAP_MULTIPLIER = 2;
153	// Claim-side threshold — a separate business rule from the premium-side
154	// HIGH_ENCHANTMENT_THRESHOLD (5); do not merge them.
155	const CLAIM_HIGH_ENCHANTMENT_THRESHOLD = 8;
156	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
157	
158	const calculateInsuranceSum = (items: QuoteItem[]): number =>
159	  items.reduce((sum, item) => sum + ITEM_INSURANCE_VALUES[item.type], 0);
160	
161	const initialPayoutCap = (policy: QuoteStep): number =>
162	  calculateInsuranceSum(policy.items) * PAYOUT_CAP_MULTIPLIER;
163	
164	const reimbursementForDamage = (
165	  damage: Damage,
166	  insuredItems: QuoteItem[],
167	): number => {
168	  const damagedItem = insuredItems.find(
169	    (item) => item.type === damage.itemType,
170	  );
171	  const hasHighEnchantment =
172	    (damagedItem?.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_THRESHOLD;
173	  const reimbursedAmount = hasHighEnchantment
174	    ? damage.amount * HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
175	    : damage.amount;
176	  return reimbursedAmount - DEDUCTIBLE;
177	};
178	
179	const processClaim = (
180	  claimStep: ClaimStep,
181	  policy: QuoteStep,
182	  remainingCapBefore: number,
183	): ClaimResult => {
184	  const totalReimbursed = claimStep.incident.damages.reduce(
185	    (sum, damage) => sum + reimbursementForDamage(damage, policy.items),
186	    0,
187	  );
188	  const payout = Math.min(Math.floor(totalReimbursed), remainingCapBefore);
189	  return { payout, remainingCap: remainingCapBefore - payout };
190	};
191	
192	export const runScenario = (scenario: Scenario): ScenarioResult => {
193	  const remainingCaps = new Map<number, number>();
194	  const results = scenario.steps.map((step, index): StepResult => {
195	    if (step.op === "claim") {
196	      const policy = scenario.steps[step.policy] as QuoteStep;
197	      const remainingCapBefore =
198	        remainingCaps.get(step.policy) ?? initialPayoutCap(policy);
199	      const result = processClaim(step, policy, remainingCapBefore);
200	      remainingCaps.set(step.policy, result.remainingCap);
201	      return result;
202	    }
203	    const isFollowUpContract = index > 0;
204	    return {
205	      premium: calculateQuotePremium(
206	        step.items,
207	        scenario.customer,
208	        isFollowUpContract,
209	      ),
210	    };
211	  });
212	  return { results };
213	};
214

